import React, { useEffect } from 'react';
import { MotionConfig } from 'framer-motion';
import Header from './components/Header';
import Hero from './components/Hero';
import Services from './components/Services';
import Activities from './components/Activities';
import Portfolio from './components/Portfolio';
import Games from './components/Games';
import Contact from './components/Contact';
import Footer from './components/Footer';
import CustomPage from './components/CustomPage';
import AdminPanel from './admin/AdminPanel';
import TrackingTags from './components/TrackingTags';
import ScrollToTop from './components/ScrollToTop';
import SmoothScroll from './animations/SmoothScroll';
import ScrollProgress from './animations/ScrollProgress';
import { AdminDataProvider, useAdminData } from './contexts/AdminDataContext';


function AppContent() {
  const { logoConfig, remoteLoaded } = useAdminData();

  useEffect(() => {
    if (logoConfig.favicon) {
      const link = document.querySelector("link[rel='icon']") as HTMLLinkElement;
      if (link) link.href = logoConfig.favicon;
    }
    if (logoConfig.appleTouchIcon) {
      const link = document.querySelector("link[rel='apple-touch-icon']") as HTMLLinkElement;
      if (link) link.href = logoConfig.appleTouchIcon;
    }
  }, [logoConfig.favicon, logoConfig.appleTouchIcon]);

  // Attendre les données publiées : sinon le logo et le menu par défaut s'affichent puis sautent
  if (!remoteLoaded) return <div className="min-h-screen bg-blue-night" aria-busy="true" />;
  const pageSlug = new URLSearchParams(window.location.search).get('page');

  if (pageSlug) {
    return (
      <>
        <CustomPage slug={pageSlug} />
        <AdminPanel />
      </>
    );
  }

  return (
    <MotionConfig reducedMotion="user">
    <div className="App">
      <SmoothScroll />
      <ScrollProgress />
      <Header />
      <Hero />
      <Activities />
      <Services />
      <Portfolio />
      <Games />
      <Contact />
      <Footer />
      <AdminPanel />
      <TrackingTags />
      <ScrollToTop />
    </div>
    </MotionConfig>
  );
}

function App() {
  return (
    <AdminDataProvider>
      <AppContent />
    </AdminDataProvider>
  );
}

export default App;
